from pathlib import Path
import hashlib,json,secrets,sys
P=Path('/app/session-renewal-state.json')
def save(x): P.write_text(json.dumps(x,indent=2)+'\n')
def load(): return json.loads(P.read_text())
def init():
 creds=[]
 for ident,scope in [('trait-administrator','user-traits-write'),('renewal-diagnostics','session-read')]:
  token=secrets.token_urlsafe(28); Path('/app/'+ident+'.token').write_text(token+'\n'); Path('/app/'+ident+'.token').chmod(0o600); creds.append({'id':ident,'scope':scope,'token_sha256':hashlib.sha256(token.encode()).hexdigest(),'status':'accepted'})
 state={'backend_user':{'name':'alice','traits':['login:alice','db:prod-admin']},'sessions':{'ws-alice-17':{'user':'alice','current_certificate':'cert-pre-17'}},'certificates':[{'serial':'cert-pre-17','session':'ws-alice-17','traits':['login:alice','db:prod-admin'],'status':'accepted'}],'session_cache':{'ws-alice-17':{'user':'alice','traits':['login:alice','db:prod-admin']}},'connections':[{'id':'db-prod-17','certificate':'cert-pre-17','database':'production','role':'prod-admin','state':'open','outcome':'connected'},{'id':'db-denied-17','certificate':'none','database':'production','role':'guest','state':'observed','outcome':'rejected'}],'credentials':creds}; save(state)
def update_and_renew(token_path):
 s=load(); token=Path(token_path).read_text().strip(); digest=hashlib.sha256(token.encode()).hexdigest(); auth=next((x for x in s['credentials'] if x['token_sha256']==digest and x['status']=='accepted' and x['scope']=='user-traits-write'),None)
 if not auth: raise SystemExit('trait update authorization rejected')
 s['backend_user']['traits']=['login:alice']; fresh={'serial':'cert-current-17','session':'ws-alice-17','traits':list(s['backend_user']['traits']),'status':'accepted'}; s['certificates'].append(fresh); s['sessions']['ws-alice-17']['current_certificate']=fresh['serial']; save(s)
def close_controls():
 s=load(); next(x for x in s['connections'] if x['id']=='db-denied-17')['state']='closed'; next(x for x in s['credentials'] if x['id']=='renewal-diagnostics')['status']='disabled'; save(s)
if sys.argv[1]=='init': init()
elif sys.argv[1]=='renew': update_and_renew(sys.argv[2])
elif sys.argv[1]=='close-controls': close_controls()
PY
